WITH valid_accounts AS (SELECT * FROM accounts WHERE balance BETWEEN 52000 AND 71000), OpenedMonthSummary AS (SELECT DATE_FORMAT(opened_date, 'yyyy-MM') AS opened_month, COUNT(CASE WHEN account_type = 'CREDIT' THEN 1 END) AS credit_count FROM valid_accounts GROUP BY DATE_FORMAT(opened_date, 'yyyy-MM')) SELECT opened_month, credit_count FROM OpenedMonthSummary WHERE credit_count < 8;
